class Outbox:
    def __init__(self):
        self.state = {}
        self.pending = []

    def save_with_event(self, key, value, event):
        if "id" not in event or "type" not in event:
            raise ValueError("Sự kiện thiếu id hoặc type")
        self.state[key] = value
        self.pending.append(event)


class OutboxRelay:
    def __init__(self, outbox, broker):
        self.outbox = outbox
        self.broker = broker

    def relay(self):
        count = 0
        while self.outbox.pending:
            try:
                self.broker.publish(self.outbox.pending[0])
                self.outbox.pending.pop(0)
            except RuntimeError:
                break
            count += 1
        return count

def split_chunks(text, size):
    chunks = []
    for i in range(0, len(text), size):
        chunks.append(text[i:i + size])
    return chunks

def overlap_chunks(text, size, overlap):
    chunks = []
    for i in range(0, len(text), size - overlap):
        chunks.append(text[i:i + size])
    return chunks
